# 7) Aggregate helper for two-legged ties.
p=Path('src/game-engine/world-competitions.ts');s=p.read_text()
append='''\nexport type WorldAggregateScore={homeGoals:number;awayGoals:number;legsPlayed:number;legsTotal:number;winnerId?:string;decidedByPenalties:boolean};\nexport function aggregateScoreForMatch(tournament:WorldTournamentState,match:WorldCompetitionMatch):WorldAggregateScore|undefined{if(!match.tieId)return undefined;const legs=tournament.matches.filter(item=>item.tieId===match.tieId).sort((a,b)=>(a.leg??1)-(b.leg??1));if(legs.length<2)return undefined;const totals=new Map<string,number>();for(const leg of legs.filter(item=>item.played)){totals.set(leg.home.id,(totals.get(leg.home.id)??0)+(leg.homeGoals??0));totals.set(leg.away.id,(totals.get(leg.away.id)??0)+(leg.awayGoals??0));}const played=legs.filter(item=>item.played),last=played[played.length-1];return{homeGoals:totals.get(match.home.id)??0,awayGoals:totals.get(match.away.id)??0,legsPlayed:played.length,legsTotal:legs.length,winnerId:last?.winnerId,decidedByPenalties:Boolean(last?.decidedByPenalties)};}\n'''
s=s+append;p.write_text(s)

